import React, { useState, useEffect } from 'react';
import axios from 'axios';
import PageHeader from '../components/ui/PageHeader';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';

const MyLeavePage = () => {
  const [leaveData, setLeaveData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showRequestForm, setShowRequestForm] = useState(false);

  useEffect(() => {
    const fetchLeaveData = async () => {
      try {
        setIsLoading(true);
        const token = localStorage.getItem('authToken');
        const response = await axios.get(
          'http://127.0.0.1:8000/api/leave/my-leave/',
          {
            headers: { 'Authorization': `Token ${token}` }
          }
        );
        setLeaveData(response.data);
        setError(null);
      } catch (err) {
        console.error('Error fetching leave data:', err);
        setError('Failed to load leave information. Please try again later.');
      } finally {
        setIsLoading(false);
      }
    };

    fetchLeaveData();
  }, []);

  if (isLoading) {
    return (
      <main className="flex-1 bg-background-light dark:bg-background-dark">
        <PageHeader 
          title="My Leave" 
          description="Manage your leave requests and track your leave balance"
          icon="event_busy"
        />
        <div className="px-4 md:px-10 py-8">
          <div className="flex items-center justify-center h-96">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
              <p className="text-subtext-light">Loading leave information...</p>
            </div>
          </div>
        </div>
      </main>
    );
  }

  if (error) {
    return (
      <main className="flex-1 bg-background-light dark:bg-background-dark">
        <PageHeader 
          title="My Leave" 
          description="Manage your leave requests and track your leave balance"
          icon="event_busy"
        />
        <div className="px-4 md:px-10 py-8">
          <Card>
            <div className="text-center py-8">
              <span className="material-icons text-red-500 text-5xl mb-4">error_outline</span>
              <p className="text-text-light dark:text-text-dark">{error}</p>
            </div>
          </Card>
        </div>
      </main>
    );
  }

  return (
    <main className="flex-1 bg-background-light dark:bg-background-dark">
      <PageHeader 
        title="My Leave" 
        description="Manage your leave requests and track your leave balance"
        icon="event_busy"
        actions={
          <Button
            onClick={() => setShowRequestForm(true)}
            icon="add"
            variant="primary"
          >
            Request Leave
          </Button>
        }
      />

      <div className="px-4 md:px-10 py-8">
        <div className="max-w-7xl mx-auto space-y-6">
          {/* Placeholder for components */}
          <Card>
            <p className="text-text-light dark:text-text-dark">Leave page content coming soon...</p>
          </Card>
        </div>
      </div>
    </main>
  );
};

export default MyLeavePage;
